$(function () {
    var $wrapper = $("#main-wrapper");
    var desktopMin = 992;

    function isDesktop() {
        return window.innerWidth >= desktopMin;
    }

    function closeMobileSidebar() {
        $wrapper.removeClass("show-sidebar");
        $("body").removeClass("sidebar-open");
    }

    function openMobileSidebar() {
        $wrapper.addClass("show-sidebar");
        $("body").addClass("sidebar-open");
    }

    function scrollSidebarToLink(link) {
        var sidebar = document.querySelector(".left-sidebar .scroll-sidebar");
        if (!sidebar || !link) {
            return;
        }

        var sidebarRect = sidebar.getBoundingClientRect();
        var linkRect = link.getBoundingClientRect();
        var offset = linkRect.top - sidebarRect.top - sidebar.clientHeight / 2 + link.offsetHeight / 2;

        sidebar.scrollTo({
            top: sidebar.scrollTop + offset,
            behavior: "smooth",
        });
    }

    function revealActiveNav() {
        var active = document.querySelector(".left-sidebar .sidebar-link.active");
        scrollSidebarToLink(active);
    }

    function syncSidebarMode() {
        if (!$wrapper.length) {
            return;
        }

        $wrapper.attr("data-sidebartype", "full");
        $wrapper.removeClass("mini-sidebar");

        if (isDesktop()) {
            closeMobileSidebar();
        }
    }

    if ("scrollRestoration" in history) {
        history.scrollRestoration = "manual";
    }
    window.scrollTo(0, 0);

    syncSidebarMode();
    $(window).on("resize", syncSidebarMode);
    setTimeout(revealActiveNav, 80);

    $(document).on("click", ".sidebartoggler", function (event) {
        event.preventDefault();
        if (isDesktop()) {
            return;
        }
        if ($wrapper.hasClass("show-sidebar")) {
            closeMobileSidebar();
        } else {
            openMobileSidebar();
        }
    });

    $(document).on("click", ".sidebar-backdrop", function () {
        closeMobileSidebar();
    });

    $(document).on("click", ".left-sidebar .sidebar-link", function () {
        $(".left-sidebar .sidebar-link").removeClass("active");
        $(this).addClass("active");
        scrollSidebarToLink(this);
        window.scrollTo({ top: 0, behavior: "smooth" });

        if (!isDesktop()) {
            closeMobileSidebar();
        }
    });

    $(document).on("keydown", function (event) {
        if (event.key === "Escape") {
            closeMobileSidebar();
        }
    });
});
